func maskURIUserInfo(raw string) string {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" || !strings.Contains(trimmed, "://") {
		return raw
	}
	parts := strings.Split(trimmed, ",")
	changed := false
	for i, part := range parts {
		partTrimmed := strings.TrimSpace(part)
		idx := strings.Index(partTrimmed, "://")
		if idx < 0 {
			continue
		}
		scheme := partTrimmed[:idx+3]
		rest := partTrimmed[idx+3:]
		pathIdx := strings.IndexAny(rest, "/?")
		authority := rest
		pathAndQuery := ""
		if pathIdx >= 0 {
			authority = rest[:pathIdx]
			pathAndQuery = rest[pathIdx:]
		}
		atIdx := strings.LastIndex(authority, "@")
		if atIdx < 0 {
			continue
		}
		hostPort := authority[atIdx+1:]
		parts[i] = scheme + "***:***@" + hostPort + pathAndQuery
		changed = true
	}
	if !changed {
		return raw
	}
	return strings.Join(parts, ",")
}

